    return f"{n}({(n * 100 // denominator):3d}%)" if n and denominator else ""


def _spent_seconds(task):
    vals = task.get('tags', {}).get('spent', [])
    total = 0
    for value in vals:
        m = re.fullmatch(r'(\d+(?:\.\d+)?)([smhDMyY]?)', str(value))
        if not m:
            continue
        n, unit = float(m.group(1)), m.group(2)
        total += int(n * {'': 1, 's': 1, 'm': 60, 'h': 3600, 'D': 86400, 'M': 2592000, 'y': 31536000, 'Y': 31536000}[unit])
    timers = task.get('tags', {}).get('tmr', [])
    if timers and timers[0] not in ('', 'off'):
        try:
            total += max(0, int(time.time()) - int(timers[0]))
        except (TypeError, ValueError):
            pass
    return total


def _display_spent(seconds):
    if seconds <= 0:
        return ''
    if seconds < 60:
        return f'{seconds}s'
    if seconds < 3600:
        return f'{seconds / 60:.1f}m'
    if seconds < 86400:
        return f'{seconds / 3600:.1f}h'
    if seconds < 30 * 86400:
        return f'{seconds / 86400:.1f}D'
    if seconds < 365 * 86400:
        return f'{seconds / (30 * 86400):.1f}M'
    return f'{seconds / (365 * 86400):.1f}Y'


def render_stats(tasks, short=False, today=None):
    today = today or date.today()
    total = len(tasks)
    done = sum(bool(t.get('done')) for t in tasks)
    overdue = sum(bool(not t.get('done') and t.get('due') and t['due'] < today.isoformat()) for t in tasks)
    recurrent = sum(bool(t.get('rec')) for t in tasks)
    out = [f'Total todos:          {total}']
    for label, count in (('Done', done), ('Overdue', overdue)):
        if count:
            out.append(f'{label+":":22}{count} ({count*100//total if total else 0}%)')
    if recurrent:
        out.append(f'Recurrent:            {recurrent}')
    if short:
        return '\n'.join(out) + '\n'

    width = 65
    out.extend(['', 'Project         Context    Total      Done       Overdue    Spent'])
    if total == 0:
        return '\n'.join(out) + '\n'
    grand_spent = _display_spent(sum(_spent_seconds(t) for t in tasks))
    out.append(f"{'':30}{_pct(total,total):>7}    {_pct(done,total):>7}    {_pct(overdue,total):>7}{grand_spent:>5}")
    projects = sorted({p for t in tasks for p in t.get('project', t.get('projects', []))})
    if projects:
        out.append('-' * width)
    for project_index, project in enumerate(projects):
        group = [t for t in tasks if project in t.get('project', t.get('projects', []))]
        gd = sum(bool(t.get('done')) for t in group)
        go = sum(bool(not t.get('done') and t.get('due') and t['due'] < today.isoformat()) for t in group)
        group_spent = _display_spent(sum(_spent_seconds(t) for t in group))
        out.append(f"{project:<16}{'':10}    {_pct(len(group),total):>7}    {_pct(gd,len(group)):>7}    {_pct(go,len(group)):>7}{group_spent:>5}")
        contexts = sorted({c for t in group for c in t.get('context', t.get('contexts', []))})
        for context in contexts:
            cg = [t for t in group if context in t.get('context', t.get('contexts', []))]
            cd = sum(bool(t.get('done')) for t in cg)
            co = sum(bool(not t.get('done') and t.get('due') and t['due'] < today.isoformat()) for t in cg)
            context_spent = _display_spent(sum(_spent_seconds(t) for t in cg))
            out.append(f"{'':16}{context:<10}    {_pct(len(cg),len(group)):>7}    {_pct(cd,len(cg)):>7}    {_pct(co,len(cg)):>7}{context_spent:>5}")
        if project_index + 1 < len(projects):
            out.append('-' * width)
    return '\n'.join(out) + '\n'

